cd /testbed && python -c "
from sympy.ntheory.residue_ntheory import nthroot_mod, is_nthpow_residue
from sympy.ntheory.modular import primitive_root

# Let's check different primes
for p in [3, 5, 7, 11, 13, 17, 19, 23]:
    for n in [2, 3, 4, 5]:
        if (p-1) % n != 0:
            a = 0
            try:
                result = nthroot_mod(a, n, p, all_roots=True)
                print(f'p={p}, n={n}, result={result}')
            except Exception as e:
                print(f'p={p}, n={n}, error={e}')
"

